// ===== BankGPT – Code node "Prepare" =====
// Mode: Run Once for All Items. Input: { question, as_of } (as_of = "YYYY-MM-DD" or empty)
// Output: one item with the cleaned question, which snapshot to search, the text to embed,
// the two Pinecone filters, and the qualifiers the re-ranker needs.

const SNAPSHOTS = [            // number in Pinecone metadata (snap_N) -> date the site was downloaded
  { n: 1, date: '2026-05-12' },
  { n: 2, date: '2026-05-19' },
  { n: 3, date: '2026-06-09' },
  { n: 4, date: '2026-08-27' },
  { n: 5, date: '2026-09-28' },
];
const MONTHS = ['january','february','march','april','may','june','july','august','september','october','november','december'];
const MON = 'jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec|' + MONTHS.join('|');
const NUMWORDS = { one:1, two:2, three:3, four:4, five:5, six:6, seven:7, eight:8, nine:9, ten:10, eleven:11, twelve:12,
                   fifteen:15, seventeen:17, eighteen:18, twenty:20, thirty:30 };

const inp = $input.first().json;
let q = String(inp.question || inp.chatInput || '').trim();
let asOf = String(inp.as_of || '').trim();

// ---- 1. a date written in the question ("as of June 30, 2026", "in May of 2026", "6/30/2026")
function monthIdx(s) { s = s.toLowerCase().replace('.', ''); return MONTHS.findIndex(m => m.startsWith(s.slice(0, 3))); }
function pad(n) { return String(n).padStart(2, '0'); }
function monthEnd(y, m) { return new Date(Date.UTC(y, m + 1, 0)).toISOString().slice(0, 10); }
const datePatterns = [
  [new RegExp(`\\(?\\b(?:(?:as of|as at|in|on|during|for|of|back in|around|at|by)\\s+)?(?:the\\s+)?(?:end of\\s+)?(${MON})\\.?\\s+(\\d{1,2})(?:st|nd|rd|th)?,?\\s+(?:of\\s+)?(\\d{4})\\b\\)?`, 'i'),
   m => `${m[3]}-${pad(monthIdx(m[1]) + 1)}-${pad(m[2])}`],
  [new RegExp(`\\(?\\b(?:(?:as of|as at|in|on|during|for|of|back in|around|at|by)\\s+)?(?:the\\s+)?(?:end of\\s+)?(${MON})\\.?,?\\s+(?:of\\s+)?(\\d{4})\\b\\)?`, 'i'),
   m => monthEnd(+m[2], monthIdx(m[1]))],
  [/\(?\b(?:(?:as of|as at|in|on|during|for|of|at|by)\s+)?(\d{1,2})\/(\d{1,2})\/(\d{4})\b\)?/i, m => `${m[3]}-${pad(m[1])}-${pad(m[2])}`],
  [/\(?\b(?:(?:as of|as at|in|on|during|for|of|at|by)\s+)?(\d{4})-(\d{2})-(\d{2})\b\)?/i, m => `${m[1]}-${m[2]}-${m[3]}`],
];
for (const [re, toIso] of datePatterns) {
  const m = q.match(re);
  if (m) {
    const iso = toIso(m);
    if (!asOf) asOf = iso;
    q = (q.slice(0, m.index) + ' ' + q.slice(m.index + m[0].length)).replace(/\s+/g, ' ').replace(/\s+([?.!,])/g, '$1').trim();
    break;
  }
}

// ---- 2. which snapshot was current on that date
const latest = SNAPSHOTS[SNAPSHOTS.length - 1];
let snap = latest;
if (asOf) {
  const older = SNAPSHOTS.filter(s => s.date <= asOf);
  snap = older.length ? older[older.length - 1] : SNAPSHOTS[0];
}
const asOfLabel = asOf ? asOf : 'today';

// ---- 3. qualifiers the member named (used by the re-ranker)
const ql = q.toLowerCase().replace(/[–—]/g, '-');
const qlNum = ql.replace(new RegExp(`\\b(${Object.keys(NUMWORDS).join('|')})\\b(?=[\\s-]*(?:months?|years?|yrs?|mos?)\\b)`, 'g'), w => NUMWORDS[w]);
const isMortgage = /mortgage|home ?loan|refinanc|heloc|home equity|fixed conventional/.test(ql);
const terms = [];               // as written in rate tables: "60 Months", "30-Year"
for (const m of qlNum.matchAll(/\b(\d{1,3})\s*-?\s*(?:months?|mos?)\b/g)) terms.push(`${+m[1]} Month`);
for (const m of qlNum.matchAll(/\b(\d{1,2})\s*-?\s*(?:years?|yrs?)\b/g)) {
  const n = +m[1];
  if (isMortgage || n >= 10) terms.push(`${n}-Year`); else terms.push(`${n * 12} Month`);
}
const years = [...ql.matchAll(/\b(20[0-3]\d|19\d\d)\b/g)].map(m => +m[1]);
const amounts = [...ql.matchAll(/\$\s*([\d,]+(?:\.\d+)?)\s*(k\b)?/g)].map(m => parseFloat(m[1].replace(/,/g, '')) * (m[2] ? 1000 : 1));
const QUALS = ['jumbo', 'ira', 'roth', 'traditional', 'business', 'refinanc', 'purchase', 'special', 'intro', 'balance transfer',
               'hsa', 'money market', 'high-yield', 'bright', 'launchpad', 'holiday', 'mini max', 'heloc', 'student', 'boat', 'rv',
               'motorcycle', 'atv', 'platinum', 'rewards'];
const quals = QUALS.filter(w => ql.includes(w));
const qlNoWallet = ql.replace(/\b(apple|google|samsung|mobile|zelle|bill) pay\b/g, ' ');
const rateQ = /\b(rates?|apr|apy|dividend|yield|interest|percent)\b|%|how much/.test(qlNoWallet)
  || /\bwhat (does|do|will|would|did)\b.*\b(pay|earn|cost|charge)s?\b/.test(qlNoWallet);
const walletQ = /apple pay|google pay|samsung pay|mobile wallet|digital wallet|tap to pay|contactless/.test(ql);
const cardListQ = /credit cards?|visa cards?|\bcards\b/.test(ql) && !/\b(personal|business)\b/.test(ql) && !walletQ;
const hoursQ = /\b(hours?|what time|are you open|open (on|today|tomorrow|late|saturdays?|sundays?|weekends?)|closed? (on|today|saturdays?|sundays?)|closing time|opening time|lobby|drive-?up|drive-?thr(u|ough))\b/.test(ql);
const linkQ = /\b(link|url|web ?page|website|where (can|do|should) i (see|find|look|check))\b/.test(ql);
const joinQ = /\b(eligib\w*|join|become a member|membership|qualify|field of membership|who can)\b/.test(ql);

// product family named in the question -> words that appear in that product's tables/pages
const isRec = /\brecreational\b|\brvs?\b|camper|motorhome|\bboats?\b|\batvs?\b|snowmobile|jet ?ski/.test(ql);
const FAMILIES = [
  [isRec ? /$^/ : /\b(car|auto|vehicle|truck|suv|motorcycle)s?\b/, ['auto', 'motorcycle']],
  [/mortgage|home ?loan|30-year|15-year|20-year/, ['home loan', 'mortgage', 'fixed conventional']],
  [/\bcds?\b|certificate/, ['certificate']],
  [/heloc|home equity/, ['home equity', 'heloc']],
  [/credit cards?|\bvisa\b/, ['visa']],
  [/personal loan/, ['personal loan']],
  [/student/, ['student']],
  [/\bboats?\b|\brvs?\b|recreational vehicle|camper|motorhome/, ['boat', 'rv', 'recreational']],
  [/\batv|snowmobile|jet ski/, ['atv', 'snowmobile']],
  [/checking/, ['checking']],
  [/money market/, ['money market']],
  [/savings/, ['savings']],
  [/\bira\b|retirement/, ['ira']],
];
const family = [];
for (const [re, words] of FAMILIES) if (re.test(ql)) family.push(...words);

// ---- 4. text to embed: the question plus the words rate tables actually use
const extra = [];
if (!isRec && /\b(car|auto|vehicle|truck|suv)\b/.test(ql)) extra.push('auto loan');
if (isRec) extra.push('recreational loan');
if (/\bcds?\b|certificate/.test(ql)) extra.push('certificate');
if (/mortgage|home ?loan/.test(ql)) extra.push('home loan fixed conventional');
if (/credit cards?|visa/.test(ql)) extra.push('Visa credit card');
for (const t of terms) extra.push(t + (t.includes('Month') ? 's' : ''));
for (const y of years) if (/car|auto|vehicle|model/.test(ql)) extra.push(`${y} Model Year`);
if (rateQ) extra.push(/apy|dividend|savings|certificate|cd|checking|money market|ira/.test(ql) ? 'rate APY table' : 'rate APR table');
if (/savings/.test(ql) && !/health|hsa|money market|\bira\b|club|bright|youth|business|you name it/.test(ql)) extra.push('Share Savings dividend rate APY tiers');
if (walletQ) extra.push('mobile wallet: add your Dupaco debit and credit cards to Apple Pay, Google Pay or Samsung Pay');
if (cardListQ) extra.push('Platinum Visa Rewards Visa Business Platinum Visa Business Rewards Visa APR');
if (hoursQ) extra.push('Lobby hours Monday-Thursday a.m. p.m. Friday Saturday Sunday Closed Drive-up');
if (joinQ) extra.push('live or work in charter area. Dupaco serves residents in counties throughout Iowa, northwest Illinois and southwest Wisconsin');
if (linkQ && rateQ) extra.push('See rates #rates page');
const searchText = [q, ...new Set(extra)].join(' ');

// ---- 5. Pinecone filters: A = official pages only, B = everything except calculators
const snapFilter = { [`snap_${snap.n}`]: { $eq: 'true' } };
const filterA = { $and: [snapFilter, { page_type: { $in: ['rates', 'product', 'promo'] } }] };
const filterB = { $and: [snapFilter, { page_type: { $nin: ['calculator'] } }] };

return [{ json: {
  question: q, as_of: asOf, as_of_label: asOfLabel, snap: snap.n, snap_date: snap.date,
  search_text: searchText, filterA, filterB,
  terms, years, amounts, quals, rateQ, hoursQ, linkQ, joinQ, family,
} }];

// ===== BankGPT – Code node "Re-rank" =====
// Mode: Run Once for All Items.
// Reads the results of "Search A" (official pages) and "Search B" (everything but calculators),
// merges them, scores each chunk, and passes the best 8 to the answering model.
// Node names below must match your node names exactly.

const P = $('Prepare').first().json;
const matchesA = ($('Search A').first().json.matches) || [];
const matchesB = ($('Search B').first().json.matches) || [];

const TYPE_BOOST = { rates: 0.08, product: 0.06, promo: 0.03, news: 0, blog: 0, resource: 0, other: 0, pdf: -0.03, calculator: -0.10 };
const TOP_N = P.hoursQ ? 10 : 8;

// merge, de-duplicate (same chunk id, or the same text on another page)
const seen = new Map();
for (const m of [...matchesA, ...matchesB]) {
  const md = m.metadata || {};
  const body = String(md.text || '').split('\n\n').slice(1).join('\n\n').trim();
  const key = m.id || body.slice(0, 300);
  if (!seen.has(key) || seen.get(key).score < m.score) seen.set(key, { id: m.id, score: m.score, md, body });
}

const qWords = P.question.toLowerCase().match(/[a-z0-9$%.]{3,}/g) || [];
const STOP = new Set(['what','whats','the','for','and','are','your','you','does','dupaco','how','much','with','can','tell','about','this','that','have','from']);
const content = [...new Set(qWords.filter(w => !STOP.has(w)))];

function dateBoost(d) {            // newer effective / published date => small boost (2018 → 0, 2026 → 0.04)
  if (!d) return 0;
  const y = parseInt(d.slice(0, 4), 10) + (parseInt(d.slice(5, 7), 10) - 1) / 12;
  return Math.max(0, Math.min(1, (y - 2018) / 8.7)) * 0.04;
}
function yearInRange(text, y) {    // "2024-27 Model Year" contains 2025?
  for (const m of text.matchAll(/\b(20\d\d)\s*[-–]\s*(\d{2,4})\b/g)) {
    let a = +m[1], b = +m[2]; if (b < 100) b += 2000;
    if (a > b) [a, b] = [b, a];
    if (y >= a && y <= b) return true;
  }
  for (const m of text.matchAll(/\b(19|20)(\d\d)\s+Model Year \(and older\)/gi)) if (y <= +(m[1] + m[2])) return true;
  return false;
}
function amountInRange(text, amt) {
  const t = text.replace(/[–—]/g, '-');
  for (const m of t.matchAll(/\$\s*([\d,]+(?:\.\d+)?)\s*-\s*\$?\s*([\d,]+(?:\.\d+)?)/g)) {
    const a = parseFloat(m[1].replace(/,/g, '')), b = parseFloat(m[2].replace(/,/g, ''));
    if (amt >= a && amt <= b) return true;
  }
  for (const m of t.matchAll(/\$\s*([\d,]+)\s*(?:\+|and up|or more)/g)) if (amt >= parseFloat(m[1].replace(/,/g, ''))) return true;
  for (const m of t.matchAll(/\$\s*([\d,]+)\s*or less/g)) if (amt <= parseFloat(m[1].replace(/,/g, ''))) return true;
  return false;
}

// newest effective date among OFFICIAL rate tables (rates/product pages) in the results:
// any other table with an older date is probably a stale copy (promo page, PDF, old guide)
let newestOfficial = '';
for (const c of seen.values()) {
  const t = c.md.page_type, d = c.md.effective_date || '';
  if ((t === 'rates' || t === 'product') && d > newestOfficial) newestOfficial = d;
}

const scored = [];
for (const c of seen.values()) {
  const text = c.body;
  const low = text.toLowerCase();
  const type = c.md.page_type || 'other';
  let s = c.score;
  const why = [];
  s += TYPE_BOOST[type] ?? 0;
  const isTable = c.md.has_table === 'true' || /\|\s*---/.test(text);
  if (P.rateQ) {
    if (isTable) { s += 0.04; why.push('table'); }
    if (['news', 'blog', 'resource'].includes(type)) s -= 0.03;
  }
  for (const t of P.terms || []) {
    const num = t.split(/[\s-]/)[0], unit = t.includes('Year') ? 'year' : 'month';
    if (new RegExp(`\\b${num}[\\s-]*${unit}s?\\b`, 'i').test(text)) { s += 0.08; why.push(t); }
  }
  for (const y of P.years || []) if (yearInRange(text, y)) { s += 0.06; why.push(`MY ${y}`); }
  for (const a of P.amounts || []) if (amountInRange(text, a)) { s += 0.05; why.push(`$${a}`); }
  for (const qual of P.quals || []) if (low.includes(qual)) { s += 0.03; why.push(qual); }
  if ((P.family || []).length && P.family.some(w => low.includes(w))) { s += 0.06; why.push('product'); }
  if (P.hoursQ && /lobby|drive-?up|drive-?thr/i.test(text) && /\d\s*(a\.m\.|p\.m\.|am|pm)|noon/i.test(text)) {
    s += 0.15; why.push('hours');
  }
  if (P.joinQ && /count(y|ies)/i.test(text) && /iowa|illinois|wisconsin/i.test(text)) { s += 0.10; why.push('charter area'); }
  if (P.linkQ && type === 'product') { s += 0.04; why.push('product page'); }
  const eff = c.md.effective_date || '';
  if (P.rateQ && isTable && eff && newestOfficial && eff < newestOfficial && !['rates', 'product'].includes(type)) {
    s -= 0.08; why.push('older copy');
  }
  if (content.length) s += 0.10 * content.filter(w => low.includes(w)).length / content.length;
  s += dateBoost(c.md.effective_date || c.md.published_date);
  scored.push({ ...c, final: s, why });
}
scored.sort((a, b) => b.final - a.final || String(a.id).localeCompare(String(b.id)));
const top = scored.slice(0, TOP_N);

const passages = top.map((c, i) => `[${i + 1}] ${String(c.md.text || '').slice(0, 3000)}`).join('\n\n---\n\n');

return [{ json: {
  question: P.question,
  as_of: P.as_of,
  as_of_label: P.as_of_label,
  passages,
  passage_urls: top.map(c => c.md.url),
  debug: top.map(c => ({ score: +c.final.toFixed(3), sim: +c.score.toFixed(3), type: c.md.page_type,
                        date: c.md.effective_date || c.md.published_date || '', url: c.md.url, why: c.why.join(',') })),
} }];

// ===== BankGPT – Code node "Format" =====
// Mode: Run Once for All Items.
// Turns the answering model's reply into { answer, sources, confident, conflict_note }.
// Works with the different output shapes of n8n's OpenAI nodes.

const R = $('Re-rank').first().json;
const P = $('Prepare').first().json;
// main product page for each product family (the page members are sent to for that product's rates)
const FAMILY_PAGE = [
  [/\bauto\b|motorcycle/, 'https://www.dupaco.com/personal/loans/auto-motorcycle-loans'],
  [/home loan|mortgage|fixed conventional/, 'https://www.dupaco.com/personal/loans/home-loans'],
  [/home equity|heloc/, 'https://www.dupaco.com/personal/loans/home-equity'],
  [/certificate|savings|money market|\bira\b/, 'https://www.dupaco.com/personal/savings-account'],
  [/checking/, 'https://www.dupaco.com/personal/checking-accounts'],
  [/personal loan/, 'https://www.dupaco.com/personal/loans/personal-loans'],
  [/boat|\brv\b|recreational|atv|snowmobile/, 'https://www.dupaco.com/personal/loans/recreational-loans'],
];
const out = $input.first().json;

const SKIP = new Set(['type', 'format', 'id', 'model', 'role', 'status', 'object', 'finish_reason', 'refusal']);
function findText(o) {             // the model's reply text anywhere in the node output (not settings like "json_object")
  if (typeof o === 'string') return (o.includes('{') || o.includes(' ')) ? o : null;
  if (Array.isArray(o)) { for (const x of o) { const t = findText(x); if (t) return t; } return null; }
  if (o && typeof o === 'object') {
    for (const k of ['content', 'text', 'output', 'message', 'response', 'choices']) {
      if (k in o) { const t = findText(o[k]); if (t) return t; }
    }
    for (const [k, v] of Object.entries(o)) { if (SKIP.has(k)) continue; const t = findText(v); if (t) return t; }
  }
  return null;
}

function findAnswerObj(o) {        // an object with an "answer" field anywhere (JSON already parsed by n8n)
  if (o && typeof o === 'object') {
    if (!Array.isArray(o) && typeof o.answer === 'string') return o;
    for (const v of Object.values(o)) { const r = findAnswerObj(v); if (r) return r; }
  }
  return null;
}

let raw = findAnswerObj(out);
if (!raw) {
  const t = findText(out) || '';
  const m = t.match(/\{[\s\S]*\}/);
  try { raw = m ? JSON.parse(m[0]) : null; } catch (e) { raw = null; }
  if (!raw) {                      // cut-off JSON: rescue the "answer" text if it is there
    const a = t.match(/"answer"\s*:\s*"((?:[^"\\]|\\.)*)/);
    raw = a ? { answer: JSON.parse('"' + a[1].replace(/\\$/, '') + '"'), confident: true }
            : (t && !t.includes('{') ? { answer: t } : { answer: '', failed: true });
  }
}

let answer = String(raw.answer || '').trim();
const dontKnow = /\bi don'?t know\b/i.test(answer) || !answer;
if (!answer) answer = "I don't know. Please call one of our branches.";
let sources = Array.isArray(raw.sources) ? raw.sources.filter(s => typeof s === 'string' && s.startsWith('http')) : [];
if (!dontKnow && sources.length === 0) sources = (R.passage_urls || []).slice(0, 2);   // never answer without a source
if (!dontKnow) {
  // keep the model's first 4 sources, then add the product page for the product asked about,
  // the branch locator for hours questions, and the best passages
  const extra = [];
  const fam = (P.family || []).join(' ');
  for (const [re, url] of FAMILY_PAGE) if (P.rateQ && re.test(fam)) { extra.push(url); break; }
  if (P.hoursQ) extra.push('https://www.dupaco.com/contact');   // branch locator
  for (const u of (R.passage_urls || []).slice(0, 3)) extra.push(u);
  sources = [...new Set([...sources.slice(0, 4), ...extra].map(u => u.replace(/#.*$/, '')))].slice(0, 6);
}
if (dontKnow) sources = [];

// membership questions: make sure the area served is named when a passage states it
if (P.joinQ && !dontKnow && !/iowa|illinois|wisconsin/i.test(answer)) {
  // several press releases may state it; the largest county count is the newest
  const found = [...String(R.passages || '').matchAll(/\b(?:Dupaco|It) serves residents in (\d+)? ?counties[^.\n]*Wisconsin[^.\n]*\./gi)];
  found.sort((a, b) => (+b[1] || 0) - (+a[1] || 0));
  if (found.length) answer += ' ' + found[0][0].trim().replace(/^It /, 'Dupaco ');
}
// milestone questions ("how many times", recognition, awards): keep the newest milestone wording
// ("This was the fifth time ...") when the model paraphrased it as a number
const ORD = ['first','second','third','fourth','fifth','sixth','seventh','eighth','ninth','tenth','eleventh','twelfth'];
if (!dontKnow && /recogni|award|honou?r|rank|named|how many times/i.test(P.question || '')) {
  const hits = [...String(R.passages || '').matchAll(new RegExp(`[^.\\n]*\\bthe (${ORD.join('|')}) (?:consecutive )?(?:time|year)[^.\\n]*\\.`, 'gi'))];
  if (hits.length) {
    hits.sort((a, b) => ORD.indexOf(b[1].toLowerCase()) - ORD.indexOf(a[1].toLowerCase()));
    const best = hits[0];
    if (!new RegExp(`\\b${best[1]}\\b`, 'i').test(answer)) answer += ' ' + best[0].trim().replace(/^\[\d+\]\s*/, '');
  }
}
if (raw.failed) {                  // no usable reply: tell solution.py to use its local backup
  return [{ json: { answer: '', error: 'no usable model reply', sources: [], confident: false, conflict_note: null, as_of: R.as_of || null } }];
}
return [{ json: {
  answer,
  sources: [...new Set(sources)],
  confident: dontKnow ? false : (raw.confident !== false),
  conflict_note: raw.conflict_note || null,
  as_of: R.as_of || null,
} }];
